SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRANSACTION;
BEGIN TRY
    DECLARE @Now DATETIME2 = GETDATE();
    DECLARE @NowShamsi NVARCHAR(30) = CONVERT(NVARCHAR(30), @Now, 120);
    DECLARE @SeedUser NVARCHAR(150) = N'seed-pln-inventorycontrol';
    DECLARE @EntityFullName NVARCHAR(300) = N'entities.app.inv.partcardex';
    DECLARE @ActionOptions NVARCHAR(MAX) = N'[{"dataActionName":"new","enable":false,"title":"جدید"},{"dataActionName":"edit","enable":false,"title":"ویرایش"},{"dataActionName":"delete","enable":false,"title":"حذف"},{"dataActionName":"exportExcell","enable":true,"title":"خروجی اکسل"}]';

    ---------------------------------------------------------------------------
    PRINT N'=== profile Pln_InventoryControl_Report ===';
    ---------------------------------------------------------------------------
    DECLARE @NameA NVARCHAR(200) = N'Pln_InventoryControl_Report';
    DECLARE @TitleA NVARCHAR(200) = N'کنترل موجودی';
    DECLARE @QueryA NVARCHAR(MAX) = N'DECLARE @ToRaw nvarchar(30) = NULLIF(LTRIM(RTRIM(CONVERT(nvarchar(30), @ToDate))), N'''');
IF @ToRaw IS NOT NULL SET @ToRaw = LEFT(REPLACE(@ToRaw, N''-'', N''/''), 10);
DECLARE @To date = ISNULL(CASE WHEN @ToRaw IS NULL THEN NULL ELSE CAST(dbo.fn_ShamsiToMiladiDate(@ToRaw, N''/'') AS date) END, CAST(GETDATE() AS date));
DECLARE @HamkaranYear smallint = TRY_CAST(LEFT(dbo.fn_MiladiToShamsi(GETDATE()), 4) AS smallint) - 1300;
DECLARE @AYearAgo date = CAST(DATEADD(DAY, -365, GETDATE()) AS date);
;WITH Cx AS (
    SELECT c.PartId, s.HtsId AS StockHtsId, c.VQtyRatio
    FROM Inv.PartCardex AS c
    JOIN Inv.Stock AS s ON s.Id = c.StockId
    WHERE c.IsPermanentVoucher = 1 AND s.HtsId IN (6, 29, 30) AND c.[Year] = @HamkaranYear AND c.VchDateMiladiDate <= @To
),
Bal AS (
    SELECT PartId,
           CASE WHEN SUM(CASE WHEN StockHtsId = 6  THEN VQtyRatio ELSE 0 END) < 0 THEN 0 ELSE SUM(CASE WHEN StockHtsId = 6  THEN VQtyRatio ELSE 0 END) END AS Prod,
           CASE WHEN SUM(CASE WHEN StockHtsId = 29 THEN VQtyRatio ELSE 0 END) < 0 THEN 0 ELSE SUM(CASE WHEN StockHtsId = 29 THEN VQtyRatio ELSE 0 END) END AS Repair,
           CASE WHEN SUM(CASE WHEN StockHtsId = 30 THEN VQtyRatio ELSE 0 END) < 0 THEN 0 ELSE SUM(CASE WHEN StockHtsId = 30 THEN VQtyRatio ELSE 0 END) END AS Repairable
    FROM Cx GROUP BY PartId
),
InWay AS (
    SELECT o.PartId, CAST(SUM(ISNULL(o.OrderQty, 0)) - SUM(ISNULL(o.FactoredCount, 0)) AS float) AS Net
    FROM Sup.OpenOrderRequest AS o
    WHERE o.IsDeleted = 0 AND o.PartId IN (SELECT PartId FROM Bal)
    GROUP BY o.PartId
),
Guar AS (
    SELECT i.PartId, CAST(SUM(ISNULL(i.Amount, 0)) AS float) AS Mount
    FROM Sale.ProductionOrderItem AS i
    WHERE i.IsLatestVersion = 1 AND i.ProductionStep IN (210, 211, 213, 214, 215, 216, 220, 221, 246, 1376, 1380)
      AND i.PartId IN (SELECT PartId FROM Bal)
    GROUP BY i.PartId
),
Usage AS (
    SELECT c.PartId,
           SUM(CASE WHEN c.VchType = N''69'' THEN c.Qty ELSE 0 END) - SUM(CASE WHEN c.VchType = N''18'' THEN c.Qty ELSE 0 END)
         + SUM(CASE WHEN c.VchType = N''53'' THEN c.Qty ELSE 0 END) - SUM(CASE WHEN c.VchType = N''7''  THEN c.Qty ELSE 0 END)
         + SUM(CASE WHEN c.VchType = N''51'' THEN c.Qty ELSE 0 END) - SUM(CASE WHEN c.VchType = N''5''  THEN c.Qty ELSE 0 END) AS OneYear
    FROM Inv.PartCardex AS c
    JOIN Inv.Stock AS s ON s.Id = c.StockId
    WHERE s.HtsId = 6 AND c.VchDateMiladiDate >= @AYearAgo AND c.VchType IN (N''69'', N''18'', N''53'', N''7'', N''51'', N''5'')
      AND c.PartId IN (SELECT PartId FROM Bal)
    GROUP BY c.PartId
),
Lead AS (
    SELECT PartId, SUM(ISNULL(LeadTimeDay, 0)) / 30 AS Months
    FROM Pln.LeadTime GROUP BY PartId
),
Calc AS (
    SELECT v.PartId, p.Code AS PartCode, p.[Name] AS PartName,
           v.Prod, v.Repair, v.Repairable,
           CASE WHEN w.Net IS NULL OR w.Net < 0 THEN 0 ELSE w.Net END AS InternalWay,
           CAST(0 AS float) AS ForeignWay,
           ISNULL(g.Mount, 0) AS Guar,
           ISNULL(u.OneYear, 0) AS OneYear,
           l.Months AS LeadMonths
    FROM Bal AS v
    JOIN Inv.Part AS p ON p.Id = v.PartId
    LEFT JOIN InWay AS w ON w.PartId = v.PartId
    LEFT JOIN Guar AS g ON g.PartId = v.PartId
    LEFT JOIN Usage AS u ON u.PartId = v.PartId
    LEFT JOIN Lead AS l ON l.PartId = v.PartId
),
Calc2 AS (
    SELECT c.*,
           c.Prod + c.InternalWay + c.ForeignWay AS Total,
           c.Prod + c.InternalWay + c.ForeignWay - c.Guar AS Free,
           c.Prod - c.Guar AS Buffer,
           ROUND(c.OneYear / 12.0, 2) AS Monthly,
           ISNULL(c.LeadMonths, 0) AS LeadM
    FROM Calc AS c
),
Calc3 AS (
    SELECT c.*,
           CASE WHEN c.Monthly <= 0 THEN 0 ELSE ROUND(c.Free / c.Monthly, 2) END AS Response
    FROM Calc2 AS c
)
--!--mainsection
SELECT
    c.PartId AS [t1_Id],
    c.PartCode AS [t1_PartCode],
    c.PartName AS [t1_PartName],
    CAST(CASE WHEN c.LeadMonths IS NULL OR c.OneYear = 0 THEN 1 ELSE 0 END AS bit) AS [t1_HasInvalidData],
    c.Prod AS [t1_ProductWarehouseInventoryMount],
    c.InternalWay AS [t1_InternalBuyInWayMount],
    c.ForeignWay AS [t1_ForeignBuyInWayMount],
    c.Total AS [t1_TotalInventory],
    c.Guar AS [t1_GuaranteeMount],
    c.Free AS [t1_FreeInventory],
    c.Buffer AS [t1_BufferInventory],
    c.Repair AS [t1_RepairWarehouseInventoryMount],
    c.Repairable AS [t1_RepairableWarehouseInventoryMount],
    c.OneYear AS [t1_OneYearAgeUseMount],
    c.Monthly AS [t1_MonthlyConsumptionAverage],
    c.Response AS [t1_WarehouseInventoryResponseInMonth],
    c.LeadM AS [t1_LeadTimeInMonth],
    CASE WHEN c.Response < (c.LeadM + 0.5) THEN N''سفارش'' ELSE N''عدم سفارش'' END AS [t1_OrderStatus]
FROM Calc3 AS c';
    DECLARE @QueryJsonA NVARCHAR(MAX) = N'{"Tables":[],"Relations":[],"Filters":[],"CustomConditions":[],"CustomQuery":null,"Parameters":[],"Selects":null}';
