    DECLARE @ColumnsA NVARCHAR(MAX) = N'[{"TableName":"Inv.PartCardex","ColumnName":"t1_Id","DisplayName":"شناسه","Alliance":"t1_Id","Address":"c.PartId","SystemTypeName":"Long","SelectIndex":0,"Visible":false,"PrimaryKey":true,"SystemType":6,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":80,"Filterable":false,"Sortable":false,"ClassName":""},{"TableName":"Inv.PartCardex","ColumnName":"t1_PartCode","DisplayName":"کد کالا","Alliance":"t1_PartCode","Address":"c.PartCode","SystemTypeName":"String","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":0,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":110,"Filterable":true,"Sortable":true,"ClassName":""},{"TableName":"Inv.PartCardex","ColumnName":"t1_PartName","DisplayName":"نام کالا","Alliance":"t1_PartName","Address":"c.PartName","SystemTypeName":"String","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":0,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":380,"Filterable":true,"Sortable":true,"ClassName":""},{"TableName":"Inv.PartCardex","ColumnName":"t1_HasInvalidData","DisplayName":"اطلاعات ناقص","Alliance":"t1_HasInvalidData","Address":"c.HasInvalidData","SystemTypeName":"Boolean","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":1,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":"function(data, type, row) { return (data === true || data === 1 || data === ''1'' || data === ''true'') ? ''✔'' : ''''; }","IsCusto