نبار تعمیراتی","Alliance":"t1_RepairWarehouseInventoryMount","Address":"c.RepairWarehouseInventoryMount","SystemTypeName":"Decimal","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":14,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":130,"Filterable":true,"Sortable":true,"ClassName":"ltr"},{"TableName":"Inv.PartCardex","ColumnName":"t1_RepairableWarehouseInventoryMount","DisplayName":"موجودی انبار قابل تعمیر","Alliance":"t1_RepairableWarehouseInventoryMount","Address":"c.RepairableWarehouseInventoryMount","SystemTypeName":"Decimal","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":14,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":130,"Filterable":true,"Sortable":true,"ClassName":"ltr"},{"TableName":"Inv.PartCardex","ColumnName":"t1_OneYearAgeUseMount","DisplayName":"مصرف 12 ماه گذشته","Alliance":"t1_OneYearAgeUseMount","Address":"c.OneYearAgeUseMount","SystemTypeName":"Decimal","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":14,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":130,"Filterable":true,"Sortable":true,"ClassName":"ltr"},{"TableName":"Inv.PartCardex","ColumnName":"t1_MonthlyConsumptionAverage","DisplayName":"متوسط مصرف ماهیانه","Alliance":"t1_MonthlyConsumptionAverage","Address":"c.MonthlyConsumptionAverage","SystemTypeName":"Decimal","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":14,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Ren